package sarvam

import (
	"bufio"
	"bytes"
	"encoding/json"
	"strings"

	"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
)

// CalculateTokens sums per-API-call usage from token_count records at or
// after the byte offset. Sarvam emits one token_count per API call carrying
// info.last_token_usage (input/cached-input/output/reasoning tokens); events
// with a null info (rate-limit snapshots only) count toward nothing.
func (a *Agent) CalculateTokens(transcript []byte, offset int) (protocol.TokenUsageResponse, error) {
	usage := protocol.TokenUsageResponse{
		CacheCreationTokens: 0,
		SubagentTokens:      nil,
	}

	scanner := bufio.NewScanner(bytes.NewReader(transcript))
	scanner.Buffer(make([]byte, 64*1024), maxRolloutLine)
	consumed := 0
	for scanner.Scan() {
		lineStart := consumed
		consumed += len(scanner.Bytes()) + 1 // + newline
		if lineStart < offset {
			continue
		}
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var event struct {
			Type string             `json:"type"`
			Info *rolloutTokenInfo   `json:"info"`
		}
		if json.Unmarshal([]byte(line), &event) != nil || event.Type != "token_count" {
			continue
		}
		if event.Info == nil {
			continue
		}
		usage.InputTokens += event.Info.LastTokenUsage.InputTokens
		usage.CacheReadTokens += event.Info.LastTokenUsage.CachedInputTokens
		usage.OutputTokens += event.Info.LastTokenUsage.OutputTokens
		usage.APICallCount++
	}
	if err := scanner.Err(); err != nil {
		return protocol.TokenUsageResponse{}, err
	}
	return usage, nil
}

