package sarvam

import (
	"os"
	"path/filepath"
	"testing"
)

// rolloutFixture builds a synthetic rollout JSONL from the shapes verified
// against live sarvam-code sessions.
type rolloutFixture struct {
	lines []string
}

func (f *rolloutFixture) add(line string) *rolloutFixture {
	f.lines = append(f.lines, line)
	return f
}

func (f *rolloutFixture) user(text string) *rolloutFixture {
	return f.add(`{"timestamp":"2026-11-16T06:00:00.000Z","type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_text","text":` + jsonStringOf(text) + `]}}`)
}

func (f *rolloutFixture) assistant(text string) *rolloutFixture {
	return f.add(`{"timestamp":"2026-11-16T06:00:01.000Z","type":"response_item","payload":{"type":"message","role":"assistant","content":[{"type":"output_text","text":` + jsonStringOf(text) + `]}}`)
}

func (f *rolloutFixture) functionCall(name, callID, args string) *rolloutFixture {
	return f.add(`{"timestamp":"2026-11-16T06:00:02.000Z","type":"response_item","payload":{"type":"function_call","name":` + jsonStringOf(name) + `,"call_id":` + jsonStringOf(callID) + `,"arguments":` + jsonStringOf(args) + `}}`)
}

func (f *rolloutFixture) tokenCount(input, cached, output int) *rolloutFixture {
	return f.add(`{"timestamp":"2026-11-16T06:00:03.000Z","type":"event_msg","payload":{"type":"token_count","info":{"total_token_usage":{"input_tokens":` + itoa(input) + `,"cached_input_tokens":` + itoa(cached) + `,"output_tokens":` + itoa(output) + `,"reasoning_output_tokens":0,"total_tokens":` + itoa(input+cached+output) + `},"last_token_usage":{"input_tokens":` + itoa(input) + `,"cached_input_tokens":` + itoa(cached) + `,"output_tokens":` + itoa(output) + `,"reasoning_output_tokens":0,"total_tokens":` + itoa(input+cached+output) + `}}}}`)
}

func (f *rolloutFixture) emptyTokenCount() *rolloutFixture {
	return f.add(`{"timestamp":"2026-11-16T06:00:03.100Z","type":"event_msg","payload":{"type":"token_count","info":null}}`)
}

func (f *rolloutFixture) write(t *testing.T) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "rollout-test.jsonl")
	joined := ""
	for _, line := range f.lines {
		joined += line + "\n"
	}
	if err := os.WriteFile(path, []byte(joined), 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

func sampleRollout(t *testing.T) string {
	t.Helper()
	f := &rolloutFixture{}
	f.add(`{"timestamp":"2026-11-16T05:59:59.000Z","type":"session_meta","payload":{"id":"s-1","cwd":"/repo","source":"cli"}}`)
	f.user("<environment_context>\n  <cwd>/repo</cwd>\n</environment_context>")
	f.user("Create hello.txt with the word hello")
	f.assistant("I'll create the file now.")
	f.functionCall("write_file", "call-1", `{"contents":"hello","path":"hello.txt"}`)
	f.add(`{"timestamp":"2026-11-16T06:00:02.500Z","type":"response_item","payload":{"type":"function_call_output","call_id":"call-1","output":"{\"output\":\"Success\",\"metadata\":{\"exit_code\":0}}"}}`)
	f.functionCall("exec_command", "call-2", `{"cmd":"echo x > notes.md && touch readme.md","command":"echo x > notes.md && touch readme.md"}`)
	f.assistant("done")
	return f.write(t)
}

func TestGetTranscriptPosition(t *testing.T) {
	agent := New()
	path := sampleRollout(t)

	position, err := agent.GetTranscriptPosition(path)
	if err != nil {
		t.Fatal(err)
	}
	if position != 10 {
		t.Fatalf("position = %d, want 10 (one per physical line)", position)
	}

	position, err = agent.GetTranscriptPosition(filepath.Join(t.TempDir(), "missing.jsonl"))
	if err != nil || position != 0 {
		t.Fatalf("missing file: got (%d, %v), want (0, nil)", position, err)
	}
}

func TestExtractModifiedFiles(t *testing.T) {
	agent := New()
	path := sampleRollout(t)

	files, position, err := agent.ExtractModifiedFiles(path, 0)
	if err != nil {
		t.Fatal(err)
	}
	if position != 10 {
		t.Errorf("current_position = %d, want 10", position)
	}
	want := []string{"hello.txt", "notes.md", "readme.md"}
	if len(files) != len(want) {
		t.Fatalf("files = %v, want %v", files, want)
	}
	for i, file := range want {
		if files[i] != file {
			t.Errorf("files[%d] = %q, want %q", i, files[i], file)
		}
	}

	// Offset past the write_file call leaves only the exec_command files.
	files, _, err = agent.ExtractModifiedFiles(path, 6)
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != 2 || files[0] != "notes.md" || files[1] != "readme.md" {
		t.Fatalf("files from offset 6 = %v, want [notes.md readme.md]", files)
	}

	// Offset beyond the transcript yields nothing.
	files, _, err = agent.ExtractModifiedFiles(path, 999)
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != 0 {
		t.Fatalf("files from offset 999 = %v, want none", files)
	}
}

func TestExtractPrompts_SkipsHarnessContext(t *testing.T) {
	agent := New()
	path := sampleRollout(t)

	prompts, err := agent.ExtractPrompts(path, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(prompts) != 1 || prompts[0] != "Create hello.txt with the word hello" {
		t.Fatalf("prompts = %v, want the single human prompt", prompts)
	}
}

func TestExtractSummary_LastAssistantMessage(t *testing.T) {
	agent := New()
	path := sampleRollout(t)

	summary, has, err := agent.ExtractSummary(path)
	if err != nil {
		t.Fatal(err)
	}
	if !has || summary != "done" {
		t.Fatalf("summary = (%q, %v), want (\"done\", true)", summary, has)
	}
}

func TestCalculateTokens(t *testing.T) {
	agent := New()
	f := &rolloutFixture{}
	f.tokenCount(1000, 500, 200)
	f.emptyTokenCount()
	f.tokenCount(3000, 1500, 800)
	path := f.write(t)
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	usage, err := agent.CalculateTokens(data, 0)
	if err != nil {
		t.Fatal(err)
	}
	if usage.InputTokens != 4000 {
		t.Errorf("input_tokens = %d, want 4000", usage.InputTokens)
	}
	if usage.CacheReadTokens != 2000 {
		t.Errorf("cache_read_tokens = %d, want 2000", usage.CacheReadTokens)
	}
	if usage.OutputTokens != 1000 {
		t.Errorf("output_tokens = %d, want 1000", usage.OutputTokens)
	}
	if usage.APICallCount != 2 {
		t.Errorf("api_call_count = %d, want 2 (null-info events do not count)", usage.APICallCount)
	}

	// Byte offset after the first line skips that API call.
	offset := len(f.lines[0]) + 1
	usage, err = agent.CalculateTokens(data, offset)
	if err != nil {
		t.Fatal(err)
	}
	if usage.InputTokens != 3000 {
		t.Errorf("input_tokens from offset = %d, want 3000", usage.InputTokens)
	}
	if usage.APICallCount != 1 {
		t.Errorf("api_call_count from offset = %d, want 1", usage.APICallCount)
	}
}

func TestCompactTranscript_ProjectsEntireWireShapes(t *testing.T) {
	agent := New()
	path := sampleRollout(t)

	resp, err := agent.CompactTranscript(path)
	if err != nil {
		t.Fatal(err)
	}
	decoded, err := base64Decode(resp.Transcript)
	if err != nil {
		t.Fatal(err)
	}

	lines := splitLines(string(decoded))
	if len(lines) != 5 {
		t.Fatalf("projected %d lines, want 5 (user, assistant, tool_use, tool_result, assistant):\n%s", len(lines), decoded)
	}

	var first struct {
		Type    string `json:"type"`
		Message struct {
			Role    string `json:"role"`
			Content []struct {
				Type string `json:"type"`
				Text string `json:"text"`
			} `json:"content"`
		} `json:"message"`
	}
	unmarshalStrict(t, lines[0], &first)
	if first.Type != "user" || first.Message.Role != "user" {
		t.Errorf("first projected line = %+v, want the human user message", first)
	}
	if len(first.Message.Content) != 1 || first.Message.Content[0].Text != "Create hello.txt with the word hello" {
		t.Errorf("first projected content = %+v", first.Message.Content)
	}

	var toolUse struct {
		Type    string `json:"type"`
		Message struct {
			Role    string `json:"role"`
			Content []struct {
				Type  string         `json:"type"`
				ID    string         `json:"id"`
				Name  string         `json:"name"`
				Input map[string]any `json:"input"`
			} `json:"content"`
		} `json:"message"`
	}
	unmarshalStrict(t, lines[2], &toolUse)
	if toolUse.Type != "assistant" || toolUse.Message.Role != "assistant" {
		t.Errorf("tool_use line kind = %s/%s", toolUse.Type, toolUse.Message.Role)
	}
	if len(toolUse.Message.Content) != 1 || toolUse.Message.Content[0].Type != "tool_use" {
		t.Fatalf("tool_use content = %+v", toolUse.Message.Content)
	}
	block := toolUse.Message.Content[0]
	if block.Name != "write_file" || block.ID != "call-1" {
		t.Errorf("tool_use block = %+v", block)
	}
	if block.Input["path"] != "hello.txt" {
		t.Errorf("tool_use input = %+v, want parsed arguments", block.Input)
	}

	var toolResult struct {
		Type    string `json:"type"`
		Message struct {
			Content []struct {
				Type      string `json:"type"`
				ToolUseID string `json:"tool_use_id"`
				Content   string `json:"content"`
			} `json:"content"`
		} `json:"message"`
	}
	unmarshalStrict(t, lines[3], &toolResult)
	if toolResult.Type != "user" {
		t.Errorf("tool_result line type = %s", toolResult.Type)
	}
	if len(toolResult.Message.Content) != 1 || toolResult.Message.Content[0].ToolUseID != "call-1" {
		t.Fatalf("tool_result content = %+v", toolResult.Message.Content)
	}
	if !contains(toolResult.Message.Content[0].Content, "Success") {
		t.Errorf("tool_result content = %q, want the raw output", toolResult.Message.Content[0].Content)
	}

	// The harness-context user line must be gone.
	for _, line := range lines {
		if contains(line, "environment_context") {
			t.Errorf("harness context leaked into the projected transcript: %s", line)
		}
	}
}

package sarvam

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"testing"
)

func jsonStringOf(s string) string {
	encoded, err := json.Marshal(s)
	if err != nil {
		return `""`
	}
	return string(encoded)
}

func itoa(v int) string {
	return strconv.Itoa(v)
}

func base64Decode(s string) ([]byte, error) {
	return base64.StdEncoding.DecodeString(s)
}

func splitLines(s string) []string {
	return strings.Split(strings.TrimSuffix(s, "\n"), "\n")
}

func unmarshalStrict(t *testing.T, data string, v any) {
	t.Helper()
	if err := json.Unmarshal([]byte(data), v); err != nil {
		t.Fatalf("unmarshal %s: %v", preview(data), err)
	}
}

func contains(s, sub string) bool {
	return strings.Contains(s, sub)
}

func preview(s string) string {
	if len(s) > 80 {
		return fmt.Sprintf("%.80s…", s)
	}
	return s
}

package sarvam

import (
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/external-agents/agents/entire-agent-sarvam/internal/protocol"
)

func TestInfo(t *testing.T) {
	agent := New()
	info := agent.Info()

	if info.ProtocolVersion != 1 {
		t.Errorf("protocol_version = %d, want 1", info.ProtocolVersion)
	}
	if info.Name != AgentName {
		t.Errorf("name = %q, want %q", info.Name, AgentName)
	}
	if info.Type != AgentType {
		t.Errorf("type = %q, want %q", info.Type, AgentType)
	}
	if info.IsPreview != true {
		t.Error("is_preview must be true while the integration is in preview")
	}
	if len(info.HookNames) != len(hookSpecs) {
		t.Fatalf("hook_names = %v, want one per installed event", info.HookNames)
	}
	caps := info.Capabilities
	if !caps.Hooks || !caps.TranscriptAnalyzer || !caps.CompactTranscript || !caps.TokenCalculator || !caps.UsesTerminal {
		t.Errorf("declared capabilities = %+v", caps)
	}
	if caps.TextGenerator || caps.HookResponseWriter || caps.SubagentAwareExtractor || caps.TranscriptPreparer {
		t.Errorf("undeclared capabilities must be false: %+v", caps)
	}
}

func TestDetect(t *testing.T) {
	agent := &Agent{LookPath: func(string) (string, error) {
		return "", errors.New("not found")
	}}
	if agent.Detect().Present {
		t.Error("detect must be false when the CLI is off PATH and SARVAM_HOME is absent")
	}

	agent = &Agent{LookPath: func(name string) (string, error) {
		if name == sarvamBinary {
			return "/usr/local/bin/sarvam-code", nil
		}
		return "", errors.New("not found")
	}}
	if !agent.Detect().Present {
		t.Error("detect must be true when the CLI is on PATH")
	}
}

func TestGetSessionDir_RespectsSarvamHome(t *testing.T) {
	t.Setenv("SARVAM_HOME", "/custom/home")
	agent := New()

	dir, err := agent.GetSessionDir("/some/repo")
	if err != nil {
		t.Fatal(err)
	}
	if dir != filepath.Join("/custom/home", "sessions") {
		t.Fatalf("session_dir = %q, want the SARVAM_HOME sessions tree", dir)
	}
}

func TestResolveSessionFile_FallbackContainsSessionID(t *testing.T) {
	agent := New()
	dir := t.TempDir()

	path := agent.ResolveSessionFile(dir, "test-session-123")
	if path == "" {
		t.Fatal("session_file must not be empty")
	}
	if !contains(path, "test-session-123") {
		t.Fatalf("session_file %q must contain the raw session-id", path)
	}
	if filepath.Dir(path) != dir {
		t.Fatalf("session_file %q must stay inside the session dir", path)
	}
}

func TestResolveSessionFile_FindsNativeRollout(t *testing.T) {
	agent := New()
	dir := t.TempDir()

	sessionID := "01a1e2d3-8a2b-7dc2-b125-885a43ce43f5"
	native := filepath.Join(dir, "2026", "11", "16", "rollout-2026-11-16T06-27-56-"+sessionID+".jsonl")
	if err := os.MkdirAll(filepath.Dir(native), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(native, []byte("{}\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	path := agent.ResolveSessionFile(dir, sessionID)
	if path != native {
		t.Fatalf("session_file = %q, want the native rollout %q", path, native)
	}
}

func TestSessionWriteReadRoundTrip(t *testing.T) {
	agent := New()
	dir := t.TempDir()
	ref := agent.ResolveSessionFile(dir, "round-trip-session")

	session := protocol.AgentSessionJSON{
		SessionID:     "round-trip-session",
		AgentName:     AgentName,
		RepoPath:      dir,
		SessionRef:    ref,
		NativeData:    []byte(`{"test": true}`),
		ModifiedFiles: []string{"file1.go"},
		NewFiles:      []string{"file3.go"},
		DeletedFiles:  []string{},
	}
	if err := agent.WriteSession(session); err != nil {
		t.Fatal(err)
	}

	input := protocol.HookInputJSON{HookType: "session-start", SessionID: "round-trip-session", SessionRef: ref}
	readBack, err := agent.ReadSession(&input)
	if err != nil {
		t.Fatal(err)
	}
	if readBack.SessionID != session.SessionID {
		t.Errorf("session_id = %q", readBack.SessionID)
	}
	if readBack.AgentName != AgentName {
		t.Errorf("agent_name = %q", readBack.AgentName)
	}
	if readBack.SessionRef != ref {
		t.Errorf("session_ref = %q", readBack.SessionRef)
	}
	if string(readBack.NativeData) != string(session.NativeData) {
		t.Errorf("native_data = %q, want %q", readBack.NativeData, session.NativeData)
	}
	if readBack.ModifiedFiles == nil || readBack.NewFiles == nil || readBack.DeletedFiles == nil {
		t.Error("file lists must be initialized on readback")
	}
}

func TestWriteSession_WithoutRefUsesStore(t *testing.T) {
	agent := New()
	dir := t.TempDir()

	session := protocol.AgentSessionJSON{
		SessionID:  "no-ref-session",
		NativeData: []byte(`{"test": true}`),
	}
	if err := agent.WriteSession(session); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(agent.ResolveSessionFile(dir, "no-ref-session")); err != nil {
		// The write landed in the agent's own session store, not the test
		// dir; verify it exists there.
		storePath := agent.ResolveSessionFile("", "no-ref-session")
		if _, statErr := os.Stat(storePath); statErr != nil {
			t.Fatalf("session was written nowhere: %v / %v", err, statErr)
		}
		_ = os.Remove(storePath)
	}
}

func TestChunkTranscript_RoundTrip(t *testing.T) {
	agent := New()
	original := []byte("The quick brown fox jumps over the lazy dog.")

	chunks, err := agent.ChunkTranscript(original, 10)
	if err != nil {
		t.Fatal(err)
	}
	if len(chunks) != 5 {
		t.Fatalf("chunks = %d, want 5", len(chunks))
	}

	reassembled, err := agent.ReassembleTranscript(chunks)
	if err != nil {
		t.Fatal(err)
	}
	if string(reassembled) != string(original) {
		t.Fatalf("round-trip mismatch: %q != %q", reassembled, original)
	}

	if _, err := agent.ChunkTranscript(original, 0); err == nil {
		t.Error("max-size 0 must be rejected")
	}
	if _, err := agent.ChunkTranscript(original, -1); err == nil {
		t.Error("negative max-size must be rejected")
	}

	single, err := agent.ChunkTranscript(original, 1<<20)
	if err != nil {
		t.Fatal(err)
	}
	if len(single) != 1 {
		t.Fatalf("small content chunks = %d, want 1", len(single))
	}
}

func TestFormatResumeCommand(t *testing.T) {
	agent := New()

	if command := agent.FormatResumeCommand(""); !contains(command, "resume") {
		t.Fatalf("empty id: %q", command)
	}
	if command := agent.FormatResumeCommand("abc-123"); !contains(command, "abc-123") {
		t.Fatalf("command %q must carry the session id", command)
	}
	// An ID with shell metacharacters must be quoted, not interpolated raw.
	if command := agent.FormatResumeCommand("a b;rm -rf /"); contains(command, ";rm") {
		t.Fatalf("command %q must quote the id", command)
	}
}

func TestReadTranscript(t *testing.T) {
	agent := New()
	path := filepath.Join(t.TempDir(), "transcript.jsonl")
	if err := os.WriteFile(path, []byte("line1\nline2\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	data, err := agent.ReadTranscript(path)
	if err != nil {
