// sarvamHooksTrustedAndEnabled verifies the review outcome against the
// [hooks.state] table the CLI persists in the user config: every installed
// event must carry an enabled entry for this repo's project config.
func sarvamHooksTrustedAndEnabled(repoDir string) bool {
	configPath := sarvamUserConfigPath()
	if configPath == "" {
		return false
	}
	data, err := os.ReadFile(configPath)
	if err != nil {
		return false
	}
	canonical, err := filepath.EvalSymlinks(repoDir)
	if err != nil {
		canonical = repoDir
	}
	lines := strings.Split(string(data), "\n")
	for _, event := range sarvamHookStateEvents {
		prefix := `[hooks.state."` + canonical + `/.sarvam/config.toml:` + event + `:0:0"]`
		found := false
		for i, line := range lines {
			if !strings.Contains(line, prefix) {
				continue
			}
			for j := i + 1; j < len(lines) && j <= i+3; j++ {
				if strings.Contains(lines[j], "enabled = true") {
					found = true
				}
				break
			}
			break
		}
		if !found {
			return false
		}
	}
	return true
}

// sarvamUserConfigPath resolves the CLI's user config carrying [hooks.state].
func sarvamUserConfigPath() string {
	if v := os.Getenv("SARVAM_HOME"); v != "" {
		return filepath.Join(v, "config.toml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".sarvam", "config.toml")
}

// reviewSarvamHooks drives the one-time /hooks review through tmux keys:
// for each installed hook, open its row, trust it (t), enable it (space),
// and return to the table. This is the same flow a user performs by hand.
func reviewSarvamHooks(sess *TmuxSession) error {
	keys := func(keys ...string) error {
		for _, key := range keys {
			if err := sess.SendKeys(key); err != nil {
				return err
			}
			time.Sleep(400 * time.Millisecond)
		}
		return nil
	}

	if err := keys("/hooks"); err != nil {
		return err
	}
	if err := keys("Enter"); err != nil {
		return err
	}
	time.Sleep(1 * time.Second)
	for i := 0; i < sarvamInstalledHooks; i++ {
		if err := keys("Enter", "t", "Space", "Escape"); err != nil {
			return err
		}
		keys("Down")
	}
	if err := keys("Escape"); err != nil {
		return err
	}
	// The state saves land asynchronously; give them a moment before the
	// caller verifies them.
	time.Sleep(2 * time.Second)
	return nil
}

